const $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const state={page:'menu',menuLoading:true,menuError:'',sessionError:false,menu:{categories:[],products:[]},cart:{},user:null,orders:[],filter:'all',csrf:'',requestToken:null,pusher:null,realtime:'connecting',refreshBusy:false,refreshQueued:false,eventTimer:null,draft:{customer:'',notes:''},ordersLoaded:false,ordersError:'',lastOrder:null,staff:[],drawerOpen:false,checkoutPayload:null};const money=n=>'৳'+Number(n||0).toLocaleString('en-BD',{maximumFractionDigits:2});const notice=s=>{const el=$('#notice');el.textContent=s;el.style.display='block';setTimeout(()=>el.style.display='none',3600)};async function api(url,options={}){const r=await fetch((staffMode()?'/staff/api':'/api')+url,{credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},...options});const body=await r.text();let j;try{j=JSON.parse(body)}catch(e){throw Error(`API returned ${r.status} ${r.statusText||''} instead of JSON. ${!body?'Empty PHP response (check API includes and PHP errors).':body.trim().startsWith('<')?'Host returned an HTML page (check .htaccess, PHP or InfinityFree browser verification).':'Invalid API response.'}`)}if(!r.ok){if(r.status===401&&state.user){window.PWA?.onSignedOut();state.user=null;state.cart={};state.orders=[];state.ordersLoaded=false;state.draft={customer:'',notes:''};state.lastOrder=null;state.requestToken=null;state.checkoutPayload=null;if(state.pusher)state.pusher.disconnect();window.Owner?.reset();window.Ops?.stop();go('login')}const error=Error(j.error||`Request failed (${r.status})`);error.status=r.status;throw error;}if(j.installation_required&&staffMode()){location.replace('/install.php');throw Error('Opening owner setup…')}if(j.csrf)state.csrf=j.csrf;return j}const post=(url,data)=>api(url,{method:'POST',body:JSON.stringify(data)});const patch=(url,data)=>api(url,{method:'PATCH',body:JSON.stringify(data)});const can=p=>{if(!state.user||!['owner','manager'].includes(state.user.role))return false;if(state.user.role==='owner')return true;if(!['orders:view','orders:pay','products:manage','reports:view'].includes(p))return false;if(p==='orders:view')return true;return state.user.permissions?.[p]??true};

const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',order:'M6 3h12v18l-3-2-3 2-3-2-3 2Z M9 8h6 M9 12h6',menu:'M4 4h6v6H4Z M14 4h6v6h-6Z M4 14h6v6H4Z M14 14h6v6h-6Z',staff:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',report:'M4 20h16 M7 16v-5 M12 16V4 M17 16V8',account:'M20 21v-2a7 7 0 0 0-14 0v2 M13 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',logout:'M9 21H3V3h6 M14 8l5 4-5 4 M8 12h11'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.menu}"/></svg>`;
const access={home:'orders:view',desk:'orders:create',orders:'orders:view',products:'products:manage','product-form':'products:manage',categories:'products:manage','category-form':'products:manage',reports:'reports:view',expenses:'*',staff:'*','staff-form':'*','staff-reset':'*',audit:'*'};
function taskRole(){return false}
function receptionist(){return false}
function startPage(){return state.user?.role==='owner'?'home':can('orders:view')?'orders':can('products:manage')?'products':can('reports:view')?'reports':'account'}
const orderNumber=id=>String(id).padStart(6,'0');
const customerPages=['menu','cart','confirmation'];
function staffMode(){return location.pathname==='/staff'||location.pathname?.startsWith('/staff/')}
function go(page){if(page==='pending-payments'){if(!state.user){state.pendingPushRoute=true;page='orders'}else{state.pendingPushRoute=false;if(state.user.role==='owner'&&window.Owner){Owner.openTrail('pending_payment');return}state.filterOrder='pending_payment';page='orders'}}if(!staffMode()&&customerPages.includes(page)){customerNavigate(page);return}if(page==='app')page='menu';if(staffMode()&&customerPages.includes(page)){location.assign('/');return}if(!staffMode()&&!customerPages.includes(page)){location.assign('/staff/#'+page);return}if(page==='manage')page='home';if(page==='desk')page='orders';if(!customerPages.includes(page)){if(!state.user)page='login';else if(page==='login')page=startPage();else if(!access[page]&&page!=='account')page=startPage();else if(access[page]&&!can(access[page]))page=startPage()}if((receptionist()||taskRole())&&!['orders','account'].includes(page))page='orders';if(page==='confirmation'&&!state.lastOrder)page='menu';if(window.Owner?.isUploading()){notice('Wait for the photo upload to finish.');return}window.Owner?.closeEditor();state.page=page;toggleDrawer(false);history.replaceState({},'',`#${page}`);render();if(window.Owner?.active()&&window.Owner.hasPage(page))window.Owner.load(page);else if(['orders','home'].includes(page))loadOrders();if(page==='reports'&&!window.Owner?.active())loadReports();if(['staff','staff-reset'].includes(page)&&!(window.Owner?.active()&&page==='staff'))loadStaff();if(page==='audit'&&!window.Owner?.active())loadAudit();document.title=`${({home:'Overview',menu:'Our menu',cart:'Your order',confirmation:'Order received',desk:'New order',orders:'Orders',products:'Menu items',categories:'Categories',staff:'Staff',account:'Your account'})[page]||'Workspace'} · GANGCHIL`;$('#app').focus?.({preventScroll:true})}
function toggleDrawer(open){state.drawerOpen=open??!state.drawerOpen;document.body.classList.toggle('drawer-open',state.drawerOpen);const backdrop=$('#drawerBackdrop');if(backdrop)backdrop.hidden=!state.drawerOpen;$('#menuToggle')?.setAttribute('aria-expanded',String(state.drawerOpen));if(state.drawerOpen)$('#sidebar a')?.focus?.();else if(document.activeElement?.closest?.('#sidebar'))$('#menuToggle')?.focus?.()}
function nav(){document.body.classList.toggle('manager-mode',staffMode()&&state.user?.role==='manager'&&!customerPages.includes(state.page));document.body.classList.toggle('reception-mode',receptionist()||taskRole());const customer=customerPages.includes(state.page);document.body.classList.toggle('customer-mode',customer);document.body.classList.toggle('signed-out',!state.user&&!customer);$('#customerHeader').hidden=!customer;document.body.classList.toggle('owner-mode',!!window.Owner?.active());document.body.classList.toggle('owner-editor-open',false);if(window.Owner?.active())return window.Owner.nav();if(state.user?.role==='manager'&&!customer)return managerNav();if(receptionist()||taskRole()){
 $('#sidebar').innerHTML='';$('#who').textContent=state.user.name;$('#workspaceLabel').textContent='';return}
if(customer){$('#sidebar').innerHTML='';return}if(!state.user){$('#sidebar').innerHTML='';return}const groups=[['WORKSPACE',[['home','Overview','home'],['desk','New order','order'],['orders',state.user.role==='chef'?'Kitchen orders':'Orders','order']]],['RESTAURANT',[['products','Menu items','menu'],['categories','Categories','menu']]],['ADMINISTRATION',[['reports','Sales reports','report'],['staff','Staff & access','staff'],['audit','Activity log','order']]]];const parents={'product-form':'products','category-form':'categories','staff-form':'staff','staff-reset':'staff'};const active=parents[state.page]||state.page;$('#sidebar').innerHTML=`<a class="sidebar-brand" href="#${startPage()}"><img src="/logo.svg" alt="" width="40" height="40"><span>GANGCHIL<small>Restaurant workspace</small></span></a><button class="drawer-close icon-button" onclick="toggleDrawer(false)" aria-label="Close navigation">×</button><nav aria-label="Main">${groups.map(([label,links])=>{links=links.filter(([page])=>can(access[page])&&(page!=='home'||state.user.role==='owner'));return links.length?`<div class="nav-group"><p>${label}</p>${links.map(([page,label,i])=>`<a href="#${page}" class="nav-link ${active===page?'active':''}" ${active===page?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${page==='orders'?`<em class="op-payment-badge" data-payment-count ${!(window.Ops?.pending())?'hidden':''}>${window.Ops?.pending()||0}</em>`:''}</a>`).join('')}</div>`:''}).join('')}</nav><div class="sidebar-bottom"><a href="#account" class="nav-link ${state.page==='account'?'active':''}">${icon('account')}<span>Your account</span></a><button class="nav-link" onclick="logout()">${icon('logout')}<span>Sign out</span></button><p>Cash payments · Staff access only</p></div>`;window.Ops?.decorate();$('#who').textContent=state.user.name;$('#workspaceLabel').textContent=({owner:'Owner',manager:'Manager'})[state.user.role]||'Workspace'}
function pageHead(title,description='',action=''){return `<div class="page-head"><div><p class="eyebrow">${esc($('#workspaceLabel')?.textContent||'WORKSPACE')}</p><h1>${title}</h1>${description?`<p class="muted">${description}</p>`:''}</div>${action}</div>`}
function empty(title,text,action=''){return `<div class="empty-state">${icon('menu')}<h2>${title}</h2><p class="muted">${text}</p>${action}</div>`}
function render(){if(!staffMode()&&customerPages.includes(state.page)){renderCustomerSurface();return}nav();if(window.Owner?.active()&&window.Owner.hasPage(state.page)){$('#app').innerHTML=window.Owner.page(state.page);return}if(customerPages.includes(state.page))$('#customerHeader').innerHTML=customerHeader();const pages={home:homePage,menu:customerMenuPage,cart:customerCartPage,confirmation:confirmationPage,desk:menuPage,login:loginPage,orders:ordersPage,products:productsPage,'product-form':productFormPage,categories:categoriesPage,'category-form':categoryFormPage,reports:reportsPage,staff:staffPage,'staff-form':staffFormPage,'staff-reset':staffResetPage,audit:auditPage,account:()=> (receptionist()||taskRole()?'<a class="small rc-back" href="#orders">← Orders</a>':'')+accountPage()};$('#app').innerHTML=(pages[state.page]||homePage)()}
function homePage(){const pending=state.orders.filter(o=>o.status==='pending_payment').length,confirmed=state.orders.filter(o=>o.status==='confirmed').length;return `<div class="rc-heading"><div><h1>Overview</h1><p class="muted">Current order queue</p></div><button class="small" onclick="manualRefresh()">↻ Refresh</button></div><div class="manager-summary"><a href="#orders" onclick="state.filterOrder='pending_payment'"><span>Pending cash</span><strong>${state.ordersLoaded?pending:'—'}</strong></a><a href="#orders" onclick="state.filterOrder='confirmed'"><span>Receipt pending</span><strong>${state.ordersLoaded?confirmed:'—'}</strong></a></div><section class="card"><h2>Manage orders</h2><p class="muted">Receive cash and print receipts from Orders.</p><a class="btn" href="#orders">Open orders</a></section>${state.ordersError?`<p class="form-error">${esc(state.ordersError)}</p>`:''}`}
function managerNav(){
 const pages=[['home','Overview','home','orders:view'],['orders','Orders','order','orders:view'],['products','Menu','menu','products:manage'],['categories','Categories','menu','products:manage'],['reports','Reports','report','reports:view']];
 const current=({'product-form':'products','category-form':'categories'})[state.page]||state.page;
 $('#sidebar').innerHTML=`<a class="sidebar-brand" href="#home"><img src="/logo.svg" width="38" height="38" alt=""><span>GANGCHIL<small>Manager</small></span></a><button class="drawer-close icon-button" onclick="toggleDrawer(false)" aria-label="Close navigation">×</button><nav aria-label="Manager navigation">${pages.filter(p=>can(p[3])).map(([page,label,i])=>`<a href="#${page}" class="nav-link ${current===page?'active':''}" ${current===page?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${page==='orders'?`<em class="op-payment-badge" data-payment-count ${!window.Ops?.pending()?'hidden':''}>${window.Ops?.pending()||0}</em>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-link" onclick="AutoPrint.openSettings()">${icon('report')}<span>Printer setup</span></button><button class="nav-link" onclick="PWA.openSettings()">${icon('order')}<span>Notifications</span></button><button class="nav-link" onclick="Owner.toggleSound()">${icon('order')}<span>${window.Owner?.soundEnabled?.()?'Sound on':'Enable sound'}</span></button><a class="nav-link" href="/">${icon('menu')}<span>Customer menu</span></a><a class="nav-link" href="#account">${icon('account')}<span>Account</span></a><button class="nav-link" onclick="logout()">${icon('logout')}<span>Sign out</span></button></div>`;
 $('#who').textContent='';$('#workspaceLabel').textContent='Manager';window.Ops?.decorate();
}

function cartItems(){return Object.entries(state.cart).map(([id,q])=>({...state.menu.products.find(p=>String(p.id)===id),q})).filter(p=>p.id)}
function menuPage(){const items=state.menu.products.filter(p=>(state.filter==='all'||String(p.category_id)===String(state.filter))&&(!state.search||p.name.toLowerCase().includes(state.search.toLowerCase())));return `${pageHead('New order','Choose items and review the order before sending it.')} ${state.lastOrder?`<div class="order-success" role="status"><div><b>Order #${orderNumber(state.lastOrder.id)} placed · ${money(state.lastOrder.total)}</b><p>Awaiting cash confirmation. The kitchen receives it after payment.</p></div><button class="small" onclick="state.filterOrder='pending_payment';go('orders')">View orders</button><button class="icon-button" onclick="state.lastOrder=null;render()" aria-label="Dismiss confirmation">×</button></div>`:''}<button class="mobile-order-toggle" onclick="document.getElementById('currentOrder').scrollIntoView({behavior:'smooth',block:'start'})">Review current order · ${cartItems().reduce((a,p)=>a+p.q,0)} items · ${money(cartItems().reduce((a,p)=>a+Number(p.price)*p.q,0))} ↓</button><div class="pos-layout"><section id="catalog" class="catalog" aria-label="Choose menu items"><label class="search-label" for="menuSearch">Search menu</label><input id="menuSearch" type="search" placeholder="Find a dish…" value="${esc(state.search||'')}" oninput="searchMenu(this)"><div class="tabs"><button class="${state.filter==='all'?'active':''}" onclick="filter('all')">All items</button>${state.menu.categories.map(c=>`<button class="${state.filter===String(c.id)?'active':''}" onclick="filter('${c.id}')">${esc(c.name)}</button>`).join('')}</div><div class="product-grid">${items.map(p=>`<button class="dish ${p.available?'':'sold-out'}" ${p.available?'':'disabled'} onclick="add(${p.id})" aria-label="Add ${esc(p.name)} to order, ${money(p.price)}">${p.image_url?`<img src="${esc(p.image_url)}" alt="" loading="lazy">`:'<div class="dish-placeholder">'+icon('menu')+'</div>'}<div class="dish-info"><b>${esc(p.name)}</b><span class="muted">${esc(p.description||'Freshly prepared')}</span><div class="row"><strong>${money(p.price)}</strong><span class="dish-add">${p.available?'+ Add':'Sold out'}</span></div></div></button>`).join('')||empty('No items found',state.menu.products.length?'Try a different name or category.':'Add dishes from Menu items to start taking orders.')}</div></section><aside id="currentOrder" class="order-panel" aria-label="Current order">${orderPanel()}</aside></div>`}
function searchMenu(input){if(!staffMode()&&state.page==='menu'){state.search=input.value;state.customerPage=1;const results=$('#customerMenuResults');if(results)results.innerHTML=customerMenuResults();return}const start=input.selectionStart;state.search=input.value;render();const next=$('#menuSearch');next.focus();if(start!==null)next.setSelectionRange?.(start,start)}
function filter(v){state.customerPage=1;state.filter=v;render()}
function add(id){if(state.requestToken){notice('Retry this order before changing its items.');return}if((state.cart[id]||0)>=30){notice('Maximum 30 of each item per order');return}state.cart[id]=(state.cart[id]||0)+1;persistCustomerCart();render()}
function qty(id,change){if(state.requestToken){notice('Retry this order before changing its items.');return}state.cart[id]=Math.min(30,Math.max(0,(state.cart[id]||0)+change));if(!state.cart[id])delete state.cart[id];persistCustomerCart();render()}
function orderPanel(){const items=cartItems();const total=items.reduce((a,p)=>a+Number(p.price)*p.q,0);return `<div class="panel-heading"><h2>Current order</h2><span class="badge">${items.reduce((a,p)=>a+p.q,0)} items</span></div><button class="continue-order small" onclick="document.getElementById('catalog').scrollIntoView({behavior:'smooth',block:'start'})">↑ Continue adding items</button><div class="order-lines">${items.map(p=>`<div class="order-line"><div><b>${esc(p.name)}</b><small>${money(p.price)} each</small><div class="qty"><button type="button" onclick="qty(${p.id},-1)" aria-label="Remove one ${esc(p.name)}">−</button><span>${p.q}</span><button type="button" onclick="qty(${p.id},1)" aria-label="Add one ${esc(p.name)}">+</button></div></div><strong>${money(p.price*p.q)}</strong></div>`).join('')||'<p class="muted empty-order">Select a dish to start an order.</p>'}</div><form onsubmit="place(event)"><div id="formError" class="form-error" role="alert" hidden></div><label>Customer name <span class="muted">(optional)</span><input id="customer" maxlength="80" value="${esc(state.draft.customer)}" oninput="customerDraft('customer',this.value)" ${state.requestToken?'disabled':''}></label><label>Kitchen notes <span class="muted">(optional)</span><textarea id="notes" maxlength="500" placeholder="Allergies, spice level, special instructions…" oninput="customerDraft('notes',this.value)" ${state.requestToken?'disabled':''}>${esc(state.draft.notes)}</textarea></label><div class="order-total"><span>Total</span><strong>${money(total)}</strong></div><p class="muted">Cash is confirmed separately by the manager.</p><button class="btn" ${items.length?'':'disabled'}>${state.requestToken?'Retry same order':'Place order'} · ${money(total)}</button></form>`}
async function place(e){e.preventDefault();const customer=customerPages.includes(state.page);if(customer&&!state.requestToken&&!/^[1-5]$/.test(state.draft.table||'')){formError('Choose your table before placing the order.');document.getElementById('customerTableButton')?.focus?.();return}if(!cartItems().length&&!state.requestToken){formError('Choose at least one item first.');return}try{if(!state.requestToken){state.requestToken=crypto.randomUUID().replace(/-/g,'');state.checkoutPayload={request_token:state.requestToken,items:Object.entries(state.cart).map(([product_id,quantity])=>({product_id:Number(product_id),quantity})),notes:state.draft.notes,table_label:state.draft.table||''};persistCustomerCart()}const r=await post(customer?'/customer/orders':'/orders',state.checkoutPayload);state.cart={};state.draft={customer:'',notes:''};state.requestToken=null;state.checkoutPayload=null;state.lastOrder=r.order;if(customer)clearCustomerCart();if(customer)go('confirmation');else render()}catch(e){if(e.status&&e.status<500){state.requestToken=null;state.checkoutPayload=null}persistCustomerCart();render();formError(state.requestToken?'We could not confirm the connection. Your order is kept here. Tap Retry to check it without ordering twice.':e.message)}}
function customerHeader(){return `<div class="menu-hero" style="position:relative"><a href="/staff/" aria-label="Staff login" style="position:absolute;top:10px;right:16px;color:#b7c1ba;font:400 11px/1.5 system-ui,sans-serif;text-decoration:none;padding:4px 2px;z-index:2">Staff login</a><a class="customer-brand" href="/" onclick="event.preventDefault();go('menu')"><img src="/logo.svg" alt="" width="48" height="48"><span>GANGCHIL</span></a><div class="menu-brand-bn" lang="bn">গাংচিল</div><p>Kabsa, biryani and grilled chicken, cooked fresh when you order.</p></div>`}
function customerMenuPage(){const count=cartItems().reduce((n,p)=>n+p.q,0),total=cartItems().reduce((n,p)=>n+Number(p.price)*p.q,0);return `<section aria-label="Food menu"><div class="customer-menu-tools"><label class="visually-hidden" for="menuSearch">Search menu</label><input id="menuSearch" type="search" placeholder="Search dishes…" value="${esc(state.search||'')}" oninput="searchMenu(this)" ${state.menuLoading?'disabled':''}><div class="tabs"><button class="${state.filter==='all'?'active':''}" onclick="filter('all')">All dishes</button>${state.menuLoading?'<span class="menu-category-skeleton" aria-hidden="true"></span><span class="menu-category-skeleton" aria-hidden="true"></span><span class="menu-category-skeleton" aria-hidden="true"></span>':''}${state.menu.categories.map(c=>`<button class="${state.filter===String(c.id)?'active':''}" onclick="filter('${c.id}')">${esc(c.name)}</button>`).join('')}</div></div>${state.sessionError?'<p class="menu-connection-note" role="status">Connection interrupted. <button class="small" onclick="retryMenu()">Retry connection</button></p>':''}<div id="customerMenuResults">${customerMenuResults()}</div></section>${count?`<div class="customer-order-bar"><div><strong>${count} ${count===1?'item':'items'} selected</strong><span>${money(total)}</span></div><button class="btn" onclick="go('cart')">Review my order →</button></div>`:''}`}
function customerCartPage(){const items=cartItems(),total=items.reduce((n,p)=>n+Number(p.price)*p.q,0);return `<div class="customer-checkout"><a href="/" onclick="event.preventDefault();go('menu')" class="back-link">← Back to menu</a><h1>Your order</h1><p class="muted">Looking good? Check the details and send your order.</p>${items.length?`<div class="customer-review-layout"><section class="customer-review-items" aria-label="Your selected dishes">${checkoutRows(items)}<a href="/" onclick="event.preventDefault();go('menu')" class="small">+ Add more dishes</a></section><form class="customer-review-form" onsubmit="place(event)"><div id="formError" class="form-error" role="alert" hidden></div><div class="checkout-table-field"><label id="customerTableLabel" for="customerTableButton">Table <span class="required-label">Required</span></label>${TablePicker.html('customerTable',state.draft.table||'',true,!!state.requestToken)}</div><label>Anything we should know? <span class="muted">(optional)</span><textarea id="notes" maxlength="500" placeholder="Allergies or special requests…" oninput="customerDraft('notes',this.value)" ${state.requestToken?'disabled':''}>${esc(state.draft.notes)}</textarea></label><div class="order-total"><span>Total to pay</span><strong data-checkout-total>${money(total)}</strong></div><button class="btn" data-checkout-submit>${state.requestToken?'Retry my order':'Place my order'} · ${money(total)}</button></form></div>`:empty('Your order is empty','Choose something delicious from our menu.',`<button class="btn" onclick="go('menu')">Explore the menu</button>`)}</div>`}
function confirmationPage(){const o=state.lastOrder;return `<section class="customer-confirmation"><div class="confirmation-check" aria-hidden="true">✓</div><p class="eyebrow">THANK YOU</p><h1>Your order is in!</h1><p class="muted">Please keep your order number handy.</p><div class="customer-order-number"><span>ORDER NUMBER</span><strong>#${orderNumber(o.id)}</strong><b>${money(o.total)}</b></div><h2>Next: pay at the counter</h2><p>Show your order number to our team and pay in cash. Your order is confirmed once payment is received. Keep your printed receipt.</p><p role="status">Returning to the menu in <b id="confirmationCountdown">5</b> seconds…</p></section>`}
function newCustomerOrder(){state.lastOrder=null;state.search='';state.filter='all';go('menu')}
function pinField(id,label,required=true){return `<fieldset class="pin-field" data-pin-group="${id}"><legend>${label}</legend><div class="pin-boxes">${[0,1,2,3].map(i=>`<input type="password" inputmode="numeric" pattern="[0-9]" maxlength="1" autocomplete="off" aria-label="${label}, digit ${i+1} of 4" ${required?'required':''} oninput="pinInput(event)" onkeydown="pinKey(event)" onpaste="pinPaste(event)">`).join('')}</div></fieldset>`}
const asciiDigits=value=>String(value).replace(/[০-৯]/g,c=>String('০১২৩৪৫৬৭৮৯'.indexOf(c))).replace(/[^0-9]/g,'');
function readPin(id){return [...document.querySelectorAll(`[data-pin-group="${id}"] input`)].map(el=>el.value).join('')}
function pinInput(e){const field=e.target;field.value=asciiDigits(field.value).slice(-1);if(field.value)field.nextElementSibling?.focus()}
function pinKey(e){const field=e.target;if(e.key==='Backspace'&&!field.value){e.preventDefault();field.previousElementSibling?.focus()}if(e.key==='ArrowLeft'){e.preventDefault();field.previousElementSibling?.focus()}if(e.key==='ArrowRight'){e.preventDefault();field.nextElementSibling?.focus()}}
function pinPaste(e){e.preventDefault();const value=asciiDigits(e.clipboardData.getData('text')).slice(0,4);const fields=[...e.target.closest('.pin-boxes').querySelectorAll('input')];fields.forEach((el,i)=>el.value=value[i]||'');fields[Math.min(value.length,3)]?.focus()}
function loginPage(){return `<a class="back-link" href="/">← Back to customer menu</a><section class="auth-layout"><aside class="auth-story"><img src="/logo.svg" alt="" width="64" height="64"><p class="eyebrow">GANGCHIL · STAFF WORKSPACE</p><h1>Good food.<br>Great teamwork.</h1><p>One place for your restaurant’s orders, kitchen and daily service.</p><div class="auth-steps"><span>01 · Take orders</span><span>02 · Confirm cash</span><span>03 · Prepare & serve</span></div></aside><div class="auth-panel"><p class="eyebrow">WELCOME BACK</p><h2>Sign in with your PIN</h2><p class="muted">Enter your mobile number and 4-digit staff PIN.</p><form onsubmit="login(event)"><div id="formError" class="form-error" role="alert" hidden></div><label for="phone">Bangladeshi mobile number</label><input type="tel" id="phone" name="phone" required autocomplete="username" inputmode="tel" placeholder="01XXXXXXXXX" maxlength="20">${pinField('loginPin','4-digit PIN')}<button class="btn" type="submit">Sign in</button></form><details class="access-help"><summary>Forgot your PIN?</summary><p>Ask the restaurant owner to reset your staff PIN.</p></details><p class="auth-footer">Restaurant & Kabsa Place · Authorized staff only</p></div></section>`}
function formError(message){const el=$('#formError');if(el){el.textContent=message;el.hidden=false}else notice(message)}
function accountPage(){const existing=!!state.user?.has_pin;return `<h1>Your account</h1><p class="muted">${esc(state.user?.name)} · ${esc(state.user?.phone||'Mobile number not set')}</p><h2>${existing?'Mobile number & PIN':'Set up your 4-digit PIN'}</h2><form class="card editor-form" onsubmit="saveAccess(event)"><div id="formError" class="form-error" role="alert" hidden></div><label>Bangladeshi mobile number<input id="accountPhone" type="tel" inputmode="tel" autocomplete="tel" value="${esc(state.user?.phone||'')}" maxlength="20" placeholder="01XXXXXXXXX" required></label>${existing?pinField('currentPin','Current PIN'):''}${pinField('newPin',existing?'New PIN (optional)':'Choose a 4-digit PIN',!existing)}${pinField('confirmPin','Confirm new PIN',!existing)}<p class="muted">${existing?'Leave the new PIN boxes empty to keep your current PIN.':'Set your PIN before signing out. Your old password will no longer be used.'}</p><button class="btn">Save account access</button></form>`}
async function saveAccess(e){e.preventDefault();const pin=readPin('newPin'),confirm=readPin('confirmPin');if(pin!==confirm){formError('The new PINs do not match.');return}try{const r=await post('/auth/access',{phone:$('#accountPhone').value,pin:readPin('currentPin'),new_pin:pin});state.user=r.user;connect();render();notice('Account access saved')}catch(err){formError(err.message)}}
async function login(e){e.preventDefault();try{const r=await post('/auth/login',{phone:$('#phone').value,pin:readPin('loginPin')});state.user=r.user;await loadMenu();connect();state.filterOrder=undefined;const destination=state.pendingPushRoute?'pending-payments':state.afterLoginPage||startPage();state.afterLoginPage=null;go(destination);window.Ops?.start()}catch(e){formError(e.message)}}async function logout(){if(!confirm('Sign out of this workspace?'))return;try{await window.PWA?.beforeLogout();const result=await post('/auth/logout',{});state.csrf=result.csrf;state.cart={};state.draft={customer:'',notes:''};state.lastOrder=null;state.requestToken=null;state.checkoutPayload=null;state.orders=[];state.ordersLoaded=false;state.user=null;if(state.pusher){state.pusher.disconnect();state.pusher=null}window.Owner?.reset();window.Ops?.stop();clearTimeout(state.eventTimer);state.realtime='offline';go('login')}catch(e){notice('Could not sign out. '+e.message)}}
const statuses={pending_payment:'Pending cash',confirmed:'Confirmed',completed:'Completed'};const actions={pending_payment:['pay','Confirm cash','orders:pay']};function ordersPage(){return managerOrdersPage()}async function loadOrders(){if(window.Owner?.active()&&['home','orders'].includes(state.page))return window.Owner.load(state.page);if(!can('orders:view'))return false;if(state.refreshBusy){state.refreshQueued=true;return false}state.refreshBusy=true;let success=false;try{const response=await api('/orders');state.orders=response.orders;state.ordersLoaded=true;state.ordersError='';success=true;if(['orders','home'].includes(state.page))render()}catch(e){state.ordersError='Could not refresh orders. '+e.message;if(['orders','home'].includes(state.page))render();notice(state.ordersError)}finally{state.refreshBusy=false;const button=$('#refreshOrdersButton');if(button){button.disabled=false;button.textContent='↻ Refresh'}if(state.refreshQueued){state.refreshQueued=false;setTimeout(()=>loadOrders(),100)}}return success}async function manualRefresh(){const b=$('#refreshOrdersButton');if(b){b.disabled=true;b.textContent='Refreshing…'}const ok=await loadOrders();if(ok)notice('Order list refreshed · without full page reload')}async function advance(id,action){if(action==='pay')return Payment.open(id);notice('This action is no longer part of the order flow.')}

function productsPage(){return `${pageHead('Menu items','Prices, details and availability.',`<button class="btn" onclick="state.editProduct=null;go('product-form')">+ Add menu item</button>`)}<div class="data-list">${state.menu.products.map(p=>`<div class="data-row"><span class="row-main"><b>${esc(p.name)}</b><small>${esc(state.menu.categories.find(c=>String(c.id)===String(p.category_id))?.name||'Uncategorised')}</small></span><strong>${money(p.price)}</strong><span class="badge ${p.available?'ready':'cancelled'}">${p.available?'Available':'Sold out'}</span><button class="small" onclick="editProduct(${p.id})">Edit</button><button class="small" onclick="toggleProduct(${p.id},${!p.available})">${p.available?'Mark sold out':'Make available'}</button></div>`).join('')||empty('No menu items yet','Start by creating a category, then add your dishes.',`<button class="btn alt" onclick="go('categories')">Open categories</button>`)}</div>`}
