function productFormPage(){const p=state.editProduct||{};return `${pageHead(p.id?'Edit menu item':'Add menu item','Keep the details clear for staff taking orders.')}<a class="back-link" href="#products">← Back to menu items</a>${!state.menu.categories.length?'<div class="form-error">Create a category before adding items. <a href="#category-form">Add category →</a></div>':''}<form class="card editor-form" onsubmit="saveProduct(event)"><div id="formError" class="form-error" role="alert" hidden></div><label>Item name<input id="pname" required maxlength="160" value="${esc(p.name||'')}"></label><label>Description<textarea id="pdesc" maxlength="1000">${esc(p.description||'')}</textarea></label><div class="form-columns"><label>Price (BDT)<input id="pprice" type="number" step="0.01" min="0" max="1000000" required value="${p.price??''}"></label><label>Category<select id="pcat" required><option value="">Choose category</option>${state.menu.categories.map(c=>`<option value="${c.id}" ${String(c.id)===String(p.category_id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div><label>Image URL <span class="muted">(optional)</span><input id="pimage" type="url" pattern="https://.*" placeholder="https://…" value="${esc(String(p.image_url||'').startsWith('https://')?p.image_url:'')}"></label><div class="form-actions"><a class="small" href="#products">Cancel</a><button class="btn" ${state.menu.categories.length?'':'disabled'}>Save menu item</button></div></form>`}
async function saveProduct(e){e.preventDefault();try{const data={name:$('#pname').value,description:$('#pdesc').value,price:Number($('#pprice').value),category_id:Number($('#pcat').value),image_url:$('#pimage').value||state.editProduct?.image_url||null};if(state.editProduct?.id)await patch('/products/'+state.editProduct.id,data);else await post('/products',data);await loadMenu();go('products');notice('Menu item saved')}catch(e){formError(e.message)}}
async function toggleProduct(id,available){try{await patch('/products/'+id,{available});await loadMenu();if(state.page==='products')render()}catch(e){notice(e.message)}}
function categoriesPage(){return `${pageHead('Categories','Organise the ordering menu into easy-to-find groups.',`<button class="btn" onclick="go('category-form')">+ Add category</button>`)}<div class="data-list">${state.menu.categories.map(c=>`<div class="data-row"><span class="row-main"><b>${esc(c.name)}</b><small>${state.menu.products.filter(p=>String(p.category_id)===String(c.id)).length} menu items</small></span><button class="small" onclick="editCategory(${c.id})">Edit</button><button class="small" onclick="deleteCategory(${c.id})">Delete</button><button class="small" onclick="state.filter='${c.id}';go('desk')" ${can('orders:create')?'':'hidden'}>Browse items →</button></div>`).join('')||empty('No categories yet','Add a category such as Kabsa, Drinks or Sides.')}</div>`}
function categoryFormPage(){return `${pageHead('Add category')}<a class="back-link" href="#categories">← Back to categories</a><form class="card editor-form" onsubmit="createCategory(event)"><div id="formError" class="form-error" role="alert" hidden></div><label>Category name<input id="catname" required maxlength="120" placeholder="e.g. Kabsa"></label><div class="form-actions"><a class="small" href="#categories">Cancel</a><button class="btn">Save category</button></div></form>`}
async function createCategory(e){e.preventDefault();try{await post('/categories',{name:$('#catname').value});await loadMenu();go('categories');notice('Category added')}catch(e){formError(e.message)}}
function reportsPage(){return `<h1>Sales Reports</h1><div class="toolbar"><input id="from" type="date" style="width:auto" value="${new Date(Date.now()-7*86400000).toISOString().slice(0,10)}"><input id="to" type="date" style="width:auto" value="${new Date().toISOString().slice(0,10)}"><button class="btn" onclick="loadReports()">Apply</button></div><div id="reportResults">Loading...</div>`}async function loadReports(){if(!can('reports:view'))return;try{const from=$('#from')?.value||new Date(Date.now()-7*86400000).toISOString().slice(0,10),to=$('#to')?.value||new Date().toISOString().slice(0,10);const r=await api(`/reports?from=${from}&to=${to}`);if(state.page!=='reports')return;$('#reportResults').innerHTML=`<div class="grid"><div class="stat">Total Sales<strong>${money(r.sales.revenue)}</strong></div><div class="stat">Paid Orders<strong>${r.sales.orders}</strong></div></div><h2>Popular Items</h2>${r.top.map(p=>`<div class="card row">${esc(p.product_name)}<b>${p.quantity} sold</b></div>`).join('')}`}catch(e){notice(e.message)}}

function staffPage(){return `${pageHead('Staff & access','Manage team accounts and their access to the restaurant.',`<button class="btn" onclick="go('staff-form')">+ Add staff member</button>`)}<div id="staffList" class="data-list" role="status">Loading staff…</div>`}
function staffFormPage(){return `${pageHead('Add staff member','Choose the role that matches their daily work.')}<a class="back-link" href="#staff">← Back to staff</a><form class="card editor-form" onsubmit="createStaff(event)"><div id="formError" class="form-error" role="alert" hidden></div><label>Full name<input id="sname" required maxlength="120" autocomplete="name"></label><label>Bangladeshi mobile number<input type="tel" id="sphone" required maxlength="20" inputmode="tel" autocomplete="off" placeholder="01XXXXXXXXX"></label>${pinField('staffPin','4-digit staff PIN')}<label>Role<select id="srole" onchange="$('#roleHelp').textContent=roleDescription(this.value)">${['manager','owner'].map(r=>`<option>${r}</option>`).join('')}</select></label><p class="role-help muted" id="roleHelp">${roleDescription('manager')}</p><div class="form-actions"><a class="small" href="#staff">Cancel</a><button class="btn">Create staff account</button></div></form>`}
function roleDescription(role){return role==='owner'?'Full owner access.':'Manage cash confirmation and receipts.'}
function staffResetPage(){const s=state.staff.find(s=>s.id==state.resetStaffId);if(!s)return `${pageHead('Restore staff access')}<a href="#staff">← Choose a staff member</a>`;return `${pageHead('Manage staff access',esc(s.name)+' · '+esc(s.phone||'Mobile number not set'))}<a class="back-link" href="#staff">← Back to staff</a><form class="card editor-form" onsubmit="resetStaffPin(event)"><div id="formError" class="form-error" role="alert" hidden></div><label>Bangladeshi mobile number<input id="resetStaffPhone" type="tel" inputmode="tel" maxlength="20" placeholder="01XXXXXXXXX" value="${esc(s.phone||'')}" required></label>${pinField('resetPin','New 4-digit PIN (optional)',false)}<p class="muted">Leave the PIN empty to keep the existing PIN. Share a reset PIN privately.</p><div class="form-actions"><a class="small" href="#staff">Cancel</a><button class="btn">Save staff access</button></div></form>`}
async function loadStaff(){if(!can('*'))return;try{const r=await api('/staff');state.staff=r.staff;if(state.page!=='staff')return;$('#staffList').innerHTML=r.staff.map(s=>`<div class="data-row"><span class="row-main"><b>${esc(s.name)} ${s.id==state.user.id?'<span class="muted">(you)</span>':''}</b><small>${esc(s.phone||'Mobile number not set')}</small></span><span class="badge">${esc(s.role)}</span><span class="muted">${s.active?'Active':'Disabled'}</span>${s.id==state.user.id?'':`<button class="small" onclick="state.resetStaffId=${s.id};go('staff-reset')">Manage access</button><button class="small" onclick="toggleStaff(${s.id},${!s.active})">${s.active?'Disable access':'Enable access'}</button>`}</div>`).join('')}catch(e){if(state.page==='staff')$('#staffList').innerHTML=`<div class="form-error">Could not load staff. <button class="small" onclick="loadStaff()">Try again</button></div>`}}
async function createStaff(e){e.preventDefault();try{await post('/staff',{name:$('#sname').value,phone:$('#sphone').value,pin:readPin('staffPin'),role:$('#srole').value});go('staff');notice('Staff account created')}catch(e){formError(e.message)}}
async function toggleStaff(id,active){const member=state.staff.find(s=>s.id==id);if(!confirm(`${active?'Enable':'Disable'} access for ${member?.name||'this staff member'}?`))return;try{await patch('/staff/'+id,{active});loadStaff()}catch(e){notice(e.message)}}
function auditPage(){return '<h1>Audit Log</h1><div id="auditList">Loading...</div>'}async function loadAudit(){if(!can('*'))return;try{const r=await api('/audit');if(state.page!=='audit')return;$('#auditList').innerHTML=r.logs.map(l=>`<div class="card"><b>${esc(l.action)}</b> · ${esc(l.entity)} #${esc(l.entity_id)}<div class="muted">${esc(l.actor||'System')} · ${new Date(l.created_at).toLocaleString()}</div></div>`).join('')||'<div class="card">No activity yet.</div>'}catch(e){notice(e.message)}}
async function loadMenu(){state.menu=await api('/menu');state.menuLoading=false;state.menuError=''}
function setRealtime(status){state.realtime=status;if(window.Owner?.active()){window.Owner.nav();if(['home','orders'].includes(state.page))render()}else if(state.page==='orders')render()}
async function syncAfterConnection(){
  // Re-read server state, because Pusher events are transient during disconnects.
  if(['orders','home'].includes(state.page))await loadOrders();
  else if(['menu','desk','products','categories'].includes(state.page)){try{await loadMenu();render()}catch(e){notice(e.message)}}
}
async function connect(){
  if(state.pusher){state.pusher.disconnect();state.pusher=null}
  setRealtime('connecting');
  try{
    const conf=await api('/realtime/config');
    if(!state.user)return;
    if(!conf.enabled || typeof window.Pusher!=='function'){setRealtime('manual');return}
    const pusher=new window.Pusher(conf.key,{
      cluster:conf.cluster,
      forceTLS:true,
      channelAuthorization:{
        endpoint:'/staff/api/realtime/auth',
        transport:'ajax',
        headers:{'X-CSRF-Token':state.csrf}
      }
    });
    state.pusher=pusher;
    pusher.connection.bind('state_change',({current})=>{
      if(current==='disconnected'||current==='unavailable'||current==='failed')setRealtime('offline');
      if(current==='connecting'||current==='reconnecting')setRealtime('connecting');
    });
    const channel=pusher.subscribe('private-gangchil-staff');
    channel.bind('pusher:subscription_succeeded',()=>{setRealtime('live');syncAfterConnection()});
    channel.bind('pusher:subscription_error',()=>setRealtime('offline'));
    channel.bind('gangchil:changed',(event)=>{
      if(event?.kind==='order-status')window.GangchilNative?.wake?.();
      window.Ops?.changed();
      if(window.Ops?.eligible()&&event?.kind!=='menu')return;
      if(event?.kind==='menu'){
        if(['menu','desk','products','categories'].includes(state.page)){
          loadMenu().then(()=>{if(['menu','desk','products','categories'].includes(state.page))render()}).catch(()=>notice('Menu changed — tap Refresh'));
        }
        return;
      }
      // Short burst of updates = one order-list fetch, not one query per socket message.
      if(['orders','home'].includes(state.page)){
        clearTimeout(state.eventTimer);
        state.eventTimer=setTimeout(()=>loadOrders(),120);
      }else if(state.page==='desk')notice('Order update received · open Orders');
    });
  }catch(e){console.warn('Realtime connection unavailable',e);setRealtime('offline')}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user)syncAfterConnection()});
window.addEventListener('online',()=>{if(state.user&&state.realtime!=='live')syncAfterConnection()});
async function init(){
 if(state.bootBusy)return;const requestedPage=location.hash.slice(1);state.bootBusy=true;restoreCustomerCart();state.menuLoading=true;state.menuError='';state.sessionError=false;
 if(staffMode()){document.documentElement?.classList.add('staff-boot')}else{state.page='menu';renderCustomerSurface()}
 try{
  try{const me=await api('/auth/me');state.user=me.user}catch(e){state.sessionError=true;console.warn('Session could not be loaded',e.message)}
  if(staffMode()&&state.sessionError){const boot=document.getElementById('staffBoot');if(boot)boot.innerHTML='<div class="boot-brand">GANGCHIL</div><p role="alert">Could not verify your session. Please retry.</p><button class="small" onclick="retryMenu()">Retry</button>';return;}
  try{await loadMenu()}catch(e){state.menuLoading=false;state.menuError='Dishes could not be loaded. Please try again.';console.warn('Menu could not be loaded',e.message)}
  if(state.user)connect();if(!staffMode())history.replaceState({},'',location.pathname+location.search);
  if(staffMode()&&!state.user&&requestedPage&&requestedPage!=='login')state.afterLoginPage=requestedPage;go(requestedPage||(staffMode()?(state.user?startPage():'login'):'menu'));window.Ops?.start();
 }finally{state.bootBusy=false;if(!staffMode()||!state.sessionError)document.documentElement?.classList.remove('staff-boot')}
}
function retryMenu(){return init()}
init();
window.addEventListener('hashchange',()=>{if(staffMode())go(location.hash.slice(1)||(state.user?startPage():'login'));else{history.replaceState({},'',location.pathname+location.search);customerNavigate('menu',true)}});
// Lock submissions before their async handlers run; always release on completion.
document.addEventListener('submit',async event=>{const form=event.target;if(!form.matches('form'))return;const handler=form.getAttribute('onsubmit');if(!handler)return;if(form.dataset.busy){event.preventDefault();event.stopImmediatePropagation();return}form.dataset.busy='1';const button=form.querySelector('button:not([type="button"])');const label=button?.textContent;if(button){button.disabled=true;button.textContent='Please wait…'}event.preventDefault();event.stopImmediatePropagation();try{await Function('event','return '+handler)(event)}finally{delete form.dataset.busy;if(button){button.disabled=false;button.textContent=label}}},true);

async function resetStaffPin(e){e.preventDefault();try{const pin=readPin('resetPin');await patch('/staff/'+state.resetStaffId,{phone:$('#resetStaffPhone').value,...(pin?{pin}:{})});go('staff');notice('Staff access updated')}catch(err){formError(err.message)}}
window.addEventListener('keydown',event=>{window.Owner?.keydown(event);if(event.key==='Tab'&&state.drawerOpen){const controls=[...document.querySelectorAll('#sidebar a[href], #sidebar button:not([disabled])')];const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}if(event.key==='Escape'&&state.drawerOpen){toggleDrawer(false);$('#menuToggle')?.focus?.()}});

let confirmationTimer=null;let customerClosePending=false;
function customerNavigate(page,fromBack=false){
 clearInterval(confirmationTimer);confirmationTimer=null;
 if(page==='confirmation'&&!state.lastOrder)page='menu';
 if(page==='menu'&&!fromBack&&history.state?.customerSheet){customerClosePending=true;state.page='menu';toggleDrawer(false);renderCustomerSurface();history.back();return}
 const sheet=page!=='menu';
 if(!fromBack){if(sheet&&!history.state?.customerSheet)history.pushState({customerSheet:page},'',location.pathname+location.search);else history.replaceState(sheet?{customerSheet:page}:{},'',location.pathname+location.search)}
 state.page=page;toggleDrawer(false);renderCustomerSurface();
 if(page==='confirmation'){let remaining=5;confirmationTimer=setInterval(()=>{remaining--;const el=document.getElementById('confirmationCountdown');if(el)el.textContent=remaining;if(remaining<=0){clearInterval(confirmationTimer);state.lastOrder=null;go('menu')}},1000)}
}
function renderCustomerSurface(){
 const panel=document.querySelector('.customer-sheet');
 if(state.page==='cart'&&panel?.querySelector&&document.querySelector('.customer-review-items')&&cartItems().length){
  const list=document.querySelector('.customer-review-items'),scroll=list.scrollTop,focused=document.activeElement?.getAttribute?.('aria-label');
  const items=cartItems(),total=items.reduce((n,p)=>n+Number(p.price)*p.q,0);
  list.innerHTML=checkoutRows(items);list.scrollTop=scroll;
  document.querySelector('[data-checkout-total]').textContent=money(total);
  panel.querySelectorAll('input,textarea').forEach(field=>field.disabled=!!state.requestToken);
  if(document.getElementById('customerTableButton'))TablePicker.disable('customerTable',!!state.requestToken);
  document.querySelector('[data-checkout-submit]').textContent=(state.requestToken?'Retry my order':'Place my order')+' · '+money(total);
  if(focused)Array.from(list.querySelectorAll('button')).find(b=>b.getAttribute('aria-label')===focused)?.focus({preventScroll:true});
  return;
 }
 if(state.page==='cart'&&panel?.querySelector&&document.querySelector('.customer-checkout')){panel.querySelector('.customer-checkout').outerHTML=customerCartPage();return}
 nav();$('#customerHeader').innerHTML=customerHeader();
 const sheet=state.page!=='menu';
 $('#app').innerHTML='<div '+(sheet?'inert':'')+'>'+customerMenuPage()+'</div>'+(sheet?`<div class="customer-sheet-overlay"><button class="customer-sheet-backdrop" aria-label="Close order" onclick="go('menu')"></button><section class="customer-sheet" role="dialog" aria-modal="true" aria-label="Your order"><button id="closeCustomerSheet" class="icon-button customer-sheet-close" aria-label="Close order" onclick="go('menu')">×</button>${state.page==='confirmation'?confirmationPage():customerCartPage()}</section></div>`:'');
 document.body.classList.toggle('customer-sheet-open',sheet);
 if(sheet)document.getElementById('closeCustomerSheet')?.focus?.();
}
window.addEventListener('popstate',()=>{if(staffMode())return;if(customerClosePending){customerClosePending=false;history.replaceState({},'',location.pathname+location.search);customerNavigate('menu',true);return}customerNavigate(history.state?.customerSheet||'menu',true)});
window.addEventListener('keydown',e=>{if(staffMode()||state.page==='menu')return;if(e.key==='Escape'){go('menu');return}if(e.key==='Tab'){const nodes=[...document.querySelectorAll('.customer-sheet button,.customer-sheet input,.customer-sheet textarea,.customer-sheet a')].filter(x=>!x.disabled);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
async function editCategory(id){const c=state.menu.categories.find(c=>c.id==id);const name=await textDialog('Edit category','Category name',c?.name||'');if(name===null)return;try{await patch('/categories/'+id,{name});await loadMenu();render();notice('Category saved')}catch(e){notice(e.message)}}
async function deleteCategory(id){if(!confirm('Delete this category? Products must be moved first.'))return;try{await api('/categories/'+id,{method:'DELETE'});await loadMenu();render();notice('Category deleted')}catch(e){notice(e.message)}}
function textDialog(title,label,value='',maxLength=120){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='service-dialog';dialog.innerHTML=`<form method="dialog"><div class="row"><h2>${esc(title)}</h2><button value="cancel" formnovalidate class="icon-button" aria-label="Close">×</button></div><label>${esc(label)}<input maxlength="${maxLength}" value="${esc(value)}" required autofocus></label><div class="form-actions"><button value="cancel" class="small" formnovalidate>Cancel</button><button value="save" class="btn">Save & continue</button></div></form>`;dialog.addEventListener('close',()=>{const value=dialog.returnValue==='save'?dialog.querySelector('input').value.trim():null;dialog.remove();resolve(value)});document.body.appendChild(dialog);dialog.showModal()})}

function checkoutRows(items){return items.map(p=>`<div class="customer-review-line">${p.image_url?`<img class="checkout-product-image" src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy">`:`<div class="checkout-product-image checkout-image-placeholder" aria-hidden="true">${icon('menu')}</div>`}<div class="checkout-product-details"><b>${esc(p.name)}</b><p class="muted">${money(p.price)} each</p><div class="qty"><button onclick="qty(${p.id},-1)" aria-label="Remove one ${esc(p.name)}">−</button><span>${p.q}</span><button onclick="qty(${p.id},1)" aria-label="Add one ${esc(p.name)}">+</button></div></div><strong>${money(Number(p.price)*p.q)}</strong></div>`).join('')}

function acceptOrderControl(order){return `<button class="btn" onclick="Payment.receive(${order.id},this)">Cash received</button>`}

// Customer-only browser storage. Prices and final order validation stay on the server.
function persistCustomerCart(){
 if(staffMode())return;
 try{localStorage.setItem('gangchil.customer.cart.v1',JSON.stringify({version:1,cart:state.cart,draft:state.draft,requestToken:state.requestToken,checkoutPayload:state.checkoutPayload}))}catch(e){/* Storage restrictions must not prevent ordering. */}
}
function clearCustomerCart(){if(staffMode())return;try{localStorage.removeItem('gangchil.customer.cart.v1')}catch(e){}}
function customerDraft(key,value){state.draft[key]=value;persistCustomerCart()}
function restoreCustomerCart(){
 if(staffMode())return;
 try{
  const raw=localStorage.getItem('gangchil.customer.cart.v1');if(!raw||raw.length>100000)return;
  const saved=JSON.parse(raw);if(saved.version!==1||!saved.cart||typeof saved.cart!=='object'||Array.isArray(saved.cart))return;
  const cart={};for(const [id,q] of Object.entries(saved.cart).slice(0,200)){if(/^[1-9][0-9]{0,17}$/.test(id)&&Number.isInteger(q)&&q>=1&&q<=30)cart[id]=q}
  state.cart=cart;const d=saved.draft||{};state.draft={customer:typeof d.customer==='string'?d.customer.slice(0,80):'',table:typeof d.table==='string'?d.table.slice(0,40):'',notes:typeof d.notes==='string'?d.notes.slice(0,500):''};
  const p=saved.checkoutPayload,t=saved.requestToken;
  if(typeof t==='string'&&/^[a-zA-Z0-9_-]{20,80}$/.test(t)&&p?.request_token===t&&Array.isArray(p.items)&&p.items.length>0&&p.items.length<=40&&p.items.every(i=>Number.isSafeInteger(i.product_id)&&i.product_id>0&&Number.isInteger(i.quantity)&&i.quantity>=1&&i.quantity<=30)){
   state.requestToken=t;state.checkoutPayload=p;state.cart=Object.fromEntries(p.items.map(i=>[String(i.product_id),i.quantity]));
  }
 }catch(e){/* Ignore malformed or inaccessible storage. */}
}

window.Payment=(()=>{
 let dialog=null,order=null,busy=false,previousFocus=null,loadVersion=0;
 function isOpen(){return !!dialog?.open}
 function close(){if(busy)return;loadVersion++;dialog?.close();dialog?.remove();dialog=null;order=null;previousFocus?.focus?.()}
 function shell(title,content){return `<div class="payment-header"><div><p class="eyebrow">PAYMENT & TABLE</p><h2 id="paymentTitle">${title}</h2></div><button class="icon-button" aria-label="Close payment" onclick="Payment.close()">×</button></div>${content}`}
 function details(o){const assigned=TablePicker.normalize(o.table_label);return shell('Order #'+orderNumber(o.id),`<div class="payment-items">${o.items.map(i=>`<div><span>${esc(i.name)} <small>× ${i.quantity}</small></span><b>${money(Number(i.price)*i.quantity)}</b></div>`).join('')}</div>${o.customer_name?`<p class="muted">Customer: ${esc(o.customer_name)}</p>`:''}${o.notes?`<p class="order-note">${esc(o.notes)}</p>`:''}<div class="payment-amount"><span>Cash to collect</span><strong>${money(o.total)}</strong></div><div class="payment-table"><span id="paymentTableLabel">Table <small>Required</small></span>${assigned?`<div class="payment-assigned-table">Table ${assigned}</div>`:TablePicker.html('paymentTable',o.table_label,true)}</div><p class="payment-help">Confirm after receiving the cash. This confirms the order. Print the payment receipt to complete it.</p><div id="paymentError" class="form-error" role="alert" hidden></div><button class="btn payment-submit" onclick="Payment.confirmCash()">Confirm cash received · ${money(o.total)}</button>`)}
 async function open(id){
  if(!can('orders:pay')){notice('You do not have access to confirm payments.');return}
  if(busy)return;close();previousFocus=document.activeElement;const version=++loadVersion;
  dialog=document.createElement('dialog');dialog.className='payment-dialog';dialog.setAttribute('aria-labelledby','paymentTitle');dialog.innerHTML=shell('Order #'+orderNumber(id),'<p class="muted">Loading current order…</p>');dialog.addEventListener('cancel',e=>{e.preventDefault();close()});document.body.appendChild(dialog);dialog.showModal();
  try{const r=await api('/orders/'+id);if(version!==loadVersion||!dialog)return;
   order=r.order;if(order.status!=='pending_payment'){dialog.innerHTML=shell('Order #'+orderNumber(id),'<p class="form-error">This order is no longer awaiting payment. Refresh Orders to see its current status.</p>');window.Ops?.changed();return}
   dialog.innerHTML=details(order);(dialog.querySelector('#paymentTableButton')||dialog.querySelector('.payment-submit')).focus();
  }catch(e){if(version===loadVersion&&dialog)dialog.innerHTML=shell('Unable to load order','<p class="form-error">'+esc(e.message)+'</p>')}
 }
 async function confirmCash(){
  if(busy||!order||!dialog)return;const input=dialog.querySelector('#paymentTable'),table=TablePicker.normalize(order.table_label)||(input?.value||'').trim(),error=dialog.querySelector('#paymentError');
  if(!/^[1-5]$/.test(table)){error.hidden=false;error.textContent='Select table 1–5 before confirming cash.';dialog.querySelector('#paymentTableButton').setAttribute('aria-invalid','true');(dialog.querySelector('#paymentTableButton')||dialog.querySelector('.payment-submit')).focus();return}
  busy=true;if(input){input.disabled=true;TablePicker.disable('paymentTable',true);}const button=dialog.querySelector('.payment-submit');button.disabled=true;button.textContent='Confirming payment…';error.hidden=true;
  try{await post('/orders/'+order.id+'/pay',{table_label:table});const id=order.id;window.AutoPrint?.afterCash(id);busy=false;close();window.Ops?.paymentComplete(id);notice('Cash confirmed · Table '+table);await loadOrders();window.Ops?.changed()}
  catch(e){busy=false;if(!dialog)return;if(input){input.disabled=false;TablePicker.disable('paymentTable',false);}button.disabled=e.status===409;button.textContent=e.status===409?'Already updated — close and refresh':'Retry cash confirmation';error.hidden=false;error.textContent=e.message}
 }
 const receiving=new Set();
 async function receive(id,button){if(receiving.has(id)||!can('orders:pay'))return;receiving.add(id);if(button){button.disabled=true;button.textContent='Receiving…'}try{const r=await api('/orders/'+id);if(r.order.status!=='pending_payment'){window.Ops?.paymentComplete(id);notice('This order was already confirmed.');return}const table=TablePicker.normalize(r.order.table_label);if(!table){await open(id);return}await post('/orders/'+id+'/pay',{table_label:table});window.AutoPrint?.afterCash(id);window.Ops?.paymentComplete(id);notice('Cash received · Table '+table);await loadOrders();window.Ops?.changed()}catch(e){notice(e.message)}finally{receiving.delete(id);if(button?.isConnected){button.disabled=false;button.textContent='Cash received'}}}
 return {open,close,isOpen,confirmCash,details,receive,isReceiving:id=>receiving.has(id)};
})();

function managerOrdersPage(){
 const groups=[['pending_payment','Pending cash'],['confirmed','Confirmed · Receipt to print'],['completed','Completed']];const filter=state.filterOrder||'all';
 return `<div class="rc-heading"><div><h1>Orders</h1><p class="muted">Cash confirmation and receipts</p></div><div class="rc-header-actions"><button id="refreshOrdersButton" class="small" onclick="manualRefresh()">↻ Refresh</button></div></div><div class="rc-filters" aria-label="Filter orders">${[['all','All'],...groups].map(([key,label])=>`<button class="${filter===key?'active':''}" onclick="state.filterOrder='${key}';render()">${label}<span>${key==='all'?state.orders.length:state.orders.filter(o=>o.status===key).length}</span></button>`).join('')}</div><p class="rc-sync muted" data-sync-status>${window.Ops?.statusLabel()||'Connecting…'}</p>${state.ordersError?`<p class="form-error">${esc(state.ordersError)}</p>`:''}${!state.ordersLoaded?'<p class="rc-loading">Loading orders…</p>':groups.filter(([key])=>filter==='all'||key===filter).map(([key,label])=>{const rows=state.orders.filter(o=>o.status===key);return `<section class="rc-group"><div class="rc-section-title"><h2>${label}</h2><span>${rows.length}</span></div>${rows.length?`<div class="rc-grid">${rows.map(o=>`<article class="rc-card"><header><div class="rc-table"><span>TABLE</span><strong>${esc(o.table_label||'—')}</strong></div><div class="rc-order-meta"><b>#${orderNumber(o.id)}</b><span class="badge ${o.status}">${statuses[o.status]}</span></div></header><div class="rc-customer"><span>Customer</span><b>${esc(o.customer_name||'Walk-in')}</b></div><div class="rc-items">${o.items.map(i=>`<div><span>${i.quantity}× ${esc(i.name)}</span><b>${money(i.quantity*i.price)}</b></div>`).join('')}</div>${o.notes?`<p class="rc-note">${esc(o.notes)}</p>`:''}<footer><strong>${money(o.total)}</strong>${o.status==='pending_payment'&&can('orders:pay')?acceptOrderControl(o):o.status!=='pending_payment'?Receipt.controls(o):''}</footer>${o.paid_at||o.status!=='pending_payment'?Receipt.panel(o):''}</article>`).join('')}</div>`:'<p class="rc-empty">No orders here.</p>'}</section>`}).join('')}`
}

function filteredCustomerMenu(){const q=(state.search||'').trim().toLocaleLowerCase();return state.menu.products.filter(p=>(state.filter==='all'||String(p.category_id)===String(state.filter))&&(!q||[p.name,p.description,state.menu.categories.find(c=>String(c.id)===String(p.category_id))?.name].join(' ').toLocaleLowerCase().includes(q)))}
function customerMenuResults(){if(state.menuLoading)return menuSkeleton();if(state.menuError)return `<div class="menu-load-error" role="alert"><p>${esc(state.menuError)}</p><button class="btn" onclick="retryMenu()">Try again</button></div>`;const found=filteredCustomerMenu(),pages=Math.max(1,Math.ceil(found.length/12));state.customerPage=Math.min(Math.max(1,state.customerPage||1),pages);const items=found.slice((state.customerPage-1)*12,state.customerPage*12);return `<div class="customer-food-grid">${items.map(p=>`<article class="customer-dish">${p.image_url?`<button class="menu-food-art menu-food-tint-${Number(p.category_id||0)%4}" onclick="openProductImage(${p.id})" aria-label="View full photo of ${esc(p.name)}"><img src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="menu-photo-fallback" hidden aria-hidden="true">${icon('menu')}</span><span class="menu-image-zoom" aria-hidden="true">⤢</span></button>`:`<div class="menu-food-art menu-food-tint-${Number(p.category_id||0)%4}"><span class="menu-photo-fallback" aria-hidden="true">${icon('menu')}</span></div>`}<div class="customer-dish-body"><div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.description||'Prepared fresh for your order.')}</p></div><div class="row"><strong>${money(p.price)}</strong>${p.available?state.cart[p.id]?`<div class="qty"><button onclick="qty(${p.id},-1)" aria-label="Remove one ${esc(p.name)}">−</button><span>${state.cart[p.id]}</span><button onclick="qty(${p.id},1)" aria-label="Add one ${esc(p.name)}">+</button></div>`:`<button class="btn" onclick="add(${p.id})" aria-label="Add ${esc(p.name)}"><span aria-hidden="true">+</span></button>`:'<span class="badge cancelled">Sold out</span>'}</div></div></article>`).join('')||empty('Nothing here just yet',state.menu.products.length?'Try another category or search.':'Please ask a team member about today’s menu.')}</div>${customerPagination(found.length,pages)}`}
function customerPagination(total,pages){if(!total)return '';const current=state.customerPage,choices=[...new Set([1,...Array.from({length:5},(_,i)=>current+i-2).filter(n=>n>0&&n<=pages),pages])].sort((a,b)=>a-b);return `<nav class="customer-pagination" aria-label="Menu pages"><span role="status" aria-live="polite">${total} dishes · Page ${current} of ${pages}</span><div><button ${current===1?'disabled':''} onclick="customerMenuPageNumber(${current-1})" aria-label="Previous menu page">←</button>${choices.map(n=>`<button class="${n===current?'active':''}" ${n===current?'aria-current="page"':''} onclick="customerMenuPageNumber(${n})" aria-label="Menu page ${n}">${n}</button>`).join('')}<button ${current===pages?'disabled':''} onclick="customerMenuPageNumber(${current+1})" aria-label="Next menu page">→</button></div></nav>`}
function customerMenuPageNumber(page){state.customerPage=page;const root=$('#customerMenuResults');if(root){root.innerHTML=customerMenuResults();root.scrollIntoView?.({behavior:'smooth',block:'start'})}}

function menuSkeleton(){return `<div class="customer-food-grid" aria-busy="true" aria-label="Loading dishes"><span class="visually-hidden" role="status">Loading dishes…</span>${Array.from({length:6},()=>`<article class="customer-dish menu-skeleton" aria-hidden="true"><div class="menu-food-art skeleton-block"></div><div class="customer-dish-body"><div class="skeleton-line"></div><div class="skeleton-line skeleton-short"></div><div class="skeleton-line"></div></div></article>`).join('')}</div>`}
let productImageDialog=null;
function openProductImage(id){const p=state.menu.products.find(p=>p.id==id);if(!p?.image_url)return;closeProductImage();const focus=document.activeElement,dialog=document.createElement('dialog');productImageDialog=dialog;dialog.className='product-image-dialog';dialog.setAttribute('aria-labelledby','productImageTitle');dialog.innerHTML=`<div class="product-image-header"><h2 id="productImageTitle">${esc(p.name)}</h2><button class="icon-button" aria-label="Close photo" onclick="closeProductImage()">×</button></div><img src="${esc(p.image_url)}" alt="${esc(p.name)}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><p class="muted" hidden>Photo could not be loaded.</p>`;dialog.addEventListener('close',()=>{dialog.remove();if(productImageDialog===dialog)productImageDialog=null;focus?.focus?.()});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.body.appendChild(dialog);dialog.showModal()}
function closeProductImage(){productImageDialog?.close();productImageDialog=null}

window.addEventListener('pusher-ready',()=>{if(state.user)connect()});

window.TablePicker=(()=>{
 function normalize(value){const m=String(value||'').trim().match(/^(?:Table\s*)?([1-5])$/i);return m?m[1]:''}
 function html(id,value='',required=false,disabled=false){const v=normalize(value);return `<div class="table-picker" data-picker="${id}"><input type="hidden" id="${id}" value="${v}"><button type="button" id="${id}Button" class="table-picker-trigger" role="combobox" aria-haspopup="listbox" aria-expanded="false" aria-controls="${id}Options" ${required?'aria-required="true"':''} ${disabled?'disabled':''} onclick="TablePicker.toggle('${id}')" onkeydown="TablePicker.key(event,'${id}')"><span>${v?'Table '+v:'Choose a table'}</span><span aria-hidden="true">⌄</span></button><div class="table-picker-options" id="${id}Options" role="listbox" aria-label="Table" hidden>${[1,2,3,4,5].map(n=>`<button type="button" role="option" aria-selected="${v===String(n)}" onclick="TablePicker.choose('${id}','${n}')" onkeydown="TablePicker.key(event,'${id}',${n})" aria-label="Table ${n}"><span>Table</span><strong>${n}</strong></button>`).join('')}</div>${!required&&v?`<button type="button" class="table-picker-clear" onclick="TablePicker.choose('${id}','')">Clear</button>`:''}</div>`}
 function closeAll(){document.querySelectorAll('.table-picker-options').forEach(el=>el.hidden=true);document.querySelectorAll('.table-picker-trigger').forEach(el=>el.setAttribute('aria-expanded','false'))}
 function toggle(id){const options=document.getElementById(id+'Options'),open=options.hidden;closeAll();options.hidden=!open;document.getElementById(id+'Button').setAttribute('aria-expanded',String(open));if(open)options.querySelector('[aria-selected="true"]')?.focus()}
 function choose(id,value){const input=document.getElementById(id),button=document.getElementById(id+'Button');input.value=normalize(value);button.querySelector('span').textContent=input.value?'Table '+input.value:'Choose a table';button.removeAttribute('aria-invalid');document.getElementById(id+'Options').querySelectorAll('[role="option"]').forEach((node,i)=>node.setAttribute('aria-selected',String(input.value===String(i+1))));closeAll();button.focus();if(id==='customerTable')customerDraft('table',input.value)}
 function key(e,id,current){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeAll();document.getElementById(id+'Button').focus();return}if(e.key==='Tab'){closeAll();return}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const options=document.getElementById(id+'Options');options.hidden=false;document.getElementById(id+'Button').setAttribute('aria-expanded','true');const next=e.key==='Home'?1:e.key==='End'?5:Math.max(1,Math.min(5,(current||0)+(e.key==='ArrowDown'?1:-1)));options.querySelectorAll('button')[next-1]?.focus()}}
 function disable(id,on){document.getElementById(id+'Button').disabled=on;if(on)closeAll()}
 document.addEventListener('click',e=>{if(!e.target.closest?.('.table-picker'))closeAll()});return {html,normalize,toggle,choose,key,disable};
})();
window.Receipt=(()=>{
 const cache=new Map(),expanded=new Set(),attempted=new Set(),printing=new Set(),marking=new Set();
 function flag(order){if(order.receipt_submitted_at&&!order.receipt_printed_at)return '<span class="receipt-state">↗ Sent to printer</span>';return `<span class="receipt-state ${order.receipt_printed_at?'printed':'not-printed'}"><b aria-hidden="true">${order.receipt_printed_at?'✓':'×'}</b> ${order.receipt_printed_at?'Printed':'Not printed'}</span>`}
 function controls(order){return `<div class="receipt-controls" data-receipt-controls="${order.id}">${flag(order)}<button class="small" onclick="Receipt.print(${order.id})">${order.receipt_printed_at||order.receipt_submitted_at?'Reprint receipt':'Print receipt'}</button>${attempted.has(Number(order.id))&&!order.receipt_printed_at&&can('orders:pay')?`<button class="small" onclick="Receipt.complete(${order.id})">Receipt printed ✓</button>`:''}</div>`}
 function panel(order){const data=cache.get(Number(order.id));return `<details class="inline-receipt" id="inlineReceipt${order.id}" ${expanded.has(Number(order.id))?'open':''} ontoggle="Receipt.preview(${order.id},this.open)"><summary>View receipt</summary><div class="receipt-preview" id="receiptPreview${order.id}">${data?`<iframe title="Receipt #${orderNumber(order.id)}" sandbox="allow-same-origin" srcdoc="${esc(data.html)}"></iframe>`:'<p class="muted">Loading receipt…</p>'}</div></details>`}
 async function preview(id,open){id=Number(id);if(!open){expanded.delete(id);window.Ops?.changed();return}expanded.add(id);const root=document.getElementById('receiptPreview'+id);if(!root)return;try{const data=cache.get(id)||await api('/orders/'+id+'/receipt-html');cache.set(id,data);if(!expanded.has(id)||!root.isConnected)return;if(!root.querySelector('iframe')){const frame=document.createElement('iframe');frame.title='Receipt #'+orderNumber(id);frame.setAttribute('sandbox','allow-same-origin');frame.srcdoc=data.html;root.replaceChildren(frame)}}catch(e){root.textContent='Receipt could not be loaded. Close and reopen to retry.'}}
 function updateControls(order){document.querySelectorAll('[data-receipt-controls="'+order.id+'"]').forEach(root=>root.outerHTML=controls(order))}
 async function print(id){if(!window.AutoPrint){notice('Printer module has not loaded. Reload the dashboard.');return;}return AutoPrint.print(Number(id));}
 async function complete(id){id=Number(id);if(marking.has(id)||!attempted.has(id))return;marking.add(id);try{const r=await post('/orders/'+id+'/complete',{receipt_printed:true});attempted.delete(id);const saved=cache.get(id);if(saved)cache.set(id,{...saved,order:r.order});updateControls(r.order);notice('Receipt marked printed');await loadOrders();window.Ops?.changed()}catch(e){notice(e.message)}finally{marking.delete(id)}}
 return {controls,panel,preview,print,complete,flag,hasExpanded:()=>expanded.size>0,isOpen:()=>false};
})();
